KEEP={'одновр+еменно':'оба в норме','одновр+еменному':'оба в норме','зв+ёзды':'им./вин.мн.; pylem дал ударение не на ё','сл+ёзы':'ударение на ё верно','ст+ёкла':'ударение на ё верно','щ+ёки':'ударение на ё верно','кол+ёса':'ударение на ё верно','пов+ёрнут':'ударение на ё верно','дал+ёко':'форма «далёко», ударение на ё','л+юдям':'ошибка в парадигме aot','среаг+ировать':'норма реаг+ировать','н+огу':'вин.ед. н+огу','зем+ель':'род.мн. зем+ель','+адам':'английское имя +Адам','гл+ядя':'оба в норме','р+акурса':'норма р+акурс','ход+у':'«на ходу»','с+ерверной':'с+ервер','утр+ам':'«по утр+ам»','пр+игоршню':'оба в норме','с+отовые':'с+отовый','нь+ютона':'Нь+ютон','з+убчатого':'з+убчатый','шаг+у':'«на каждом шагу»','оскорбл+ю':'норма','клял+ись':'норма','норм+ированием':'оба в норме','сраб+атывание':'норма','т+олику':'норма т+олика','т+олика':'норма т+олика','з+алиты':'норма з+алиты','обруш+ение':'норма обруш+ение','обруш+ения':'норма обруш+ение','полдн+я':'«полдня пути» — полдн+я','л+инкольн':'Л+инкольн','симм+етрия':'норма','д+абы':'норма','сч+астлива':'норма сч+астлива','строк+ами':'оба в норме','аффид+евит':'как в тексте','хр+амовая':'оба в норме','п+атины':'норма п+атина','фен+омен':'оба в норме','сб+оев':'сб+оев = сбо́ев, верно','сорв+ались':'оба в норме','запер+ев':'норма запер+ев','н+иком':'«под ником»','х+а-х+а':'междометие','д+евичья':'оба в норме, д+евичья основная','з+алитого':'норма з+алитый'}
NUM=re.compile(r'(дв[аe]|тр[+]?и|чет[+]?ыре|полов[+]?иной|полт[+]?ора|\d+|с[+]?емь|в[+]?осемь|д[+]?евять|д[+]?есять|ш[+]?есть|п[+]?ять|одинн[+]?адцать|двен[+]?адцать)\s*$',re.I)
def ctxv(o):
    before=re.sub(r'\*\*.*','',o['ctx']).lower().replace('+','').rstrip(' …')
    k=o['low']
    if k=='час+а': return ('keep','после числительного — час+а')
    if k=='утр+а':
        if re.search(r'середине\s*$',before): return ('fix','+утра')
        return ('keep','«семь утр+а», «часа утр+а», «с самого утр+а»')
    if k=='след+а': return ('keep','«ни/без следа» — след+а') if re.search(r'(ни|без)\s*$',before) else ('fix','сл+еда')
    return None
def recase(orig,t):
    p=orig.replace('+',''); out='';j=0
    for ch in t:
        if ch=='+': out+='+'
        else: out+=p[j] if j<len(p) else ch; j+=1
    return out
DISP={}
# составные прилагательные/удвоения: оставляем
comp=lambda k: '-' in k and k not in FIX
sec={'fix':[],'ctx':[],'disp':[],'keep':[]}
unk=[]
for o in occ:
    k=o['low']; pl=' / '.join(o['opts'])
    if ctxv(o):
        v,x=ctxv(o); new=recase(o['orig'],x) if v=='fix' else o['orig']
        sec['ctx'].append((o,('→ '+new) if v=='fix' else 'оставить',x if v=='keep' else '',pl)); continue
    if k in FIX: sec['fix'].append((o,recase(o['orig'],FIX[k]),NOTE.get(k,''),pl))
    elif k in DISP: sec['disp'].append((o,'',DISP[k],pl))
    elif k in KEEP: sec['keep'].append((o,'',KEEP[k],pl))
    elif comp(k): sec['keep'].append((o,'',"составное слово, два ударения естественны",pl))
    else: unk.append(k)
print('UNCLASSIFIED',sorted(set(unk)))
T={'fix':'1. Меняю — текст неверен','ctx':'2. По контексту — каждое место отдельно','disp':'3. Твоё решение','keep':'4. Не трогаю — текст верен, ошибся pylem'}
out=['# Правки ударений по ⚠ — ручная проверка (26.09)','','Каждая форма просмотрена в контексте. pylem — только подсказка, вердикт мой. В текст ничего не внесено.','','Системные ошибки pylem: ударение не на ё (звёзды, слёзы, колёса…), дыры в парадигмах (людям, местный падеж), ошибки в словах вроде ракурс, толика, импульс.','']
for s in ['fix','ctx','disp','keep']:
    L=sec[s]; forms=len({o['low'] for o,*_ in L})
    out+=[f'## {T[s]} — {forms} форм, {len(L)} мест','']
    if s=='fix':
        out+=['| гл:стр | было → стало | контекст | заметка |','|---|---|---|---|']
        out+=[f"| {o['ch']}:{o['ln']} | {o['orig']} → {n} | {o['ctx']} | {nt} |" for o,n,nt,pl in L]
    elif s=='ctx':
        out+=['| гл:стр | было | решение | контекст | заметка |','|---|---|---|---|---|']
        out+=[f"| {o['ch']}:{o['ln']} | {o['orig']} | {n} | {o['ctx']} | {nt} |" for o,n,nt,pl in L]
    else:
        out+=['| гл:стр | в тексте | pylem | контекст | заметка |','|---|---|---|---|---|']
        out+=[f"| {o['ch']}:{o['ln']} | {o['orig']} | {pl} | {o['ctx']} | {nt} |" for o,_,nt,pl in L]
    out.append('')
open('/home/vellum/.local/share/vellum/assistants/juno/.vellum/workspace/narrator/reports/fine-structure-forms/fixes.md','w',encoding='utf-8').write('\n'.join(out)+'\n')
